LOG = logging.getLogger(__name__)

# Namespace to use for Nova specific metadata items in XML
NOVA_NS = "http://openstack.org/xmlns/libvirt/nova/1.1"


def make_libvirt_device_alias(identifier):
    return 'ua-%s' % identifier


def parse_libvirt_device_alias(alias):
    if alias.startswith('ua-'):
        return alias.split('-', 1)[1]
    else:
        return alias


class LibvirtConfigObject(object):

    def __init__(self, **kwargs):
        super(LibvirtConfigObject, self).__init__()

        self.root_name = kwargs.pop("root_name")
        self.ns_prefix = kwargs.pop("ns_prefix", None)
        self.ns_uri = kwargs.pop("ns_uri", None)

        # handle programmer error
        assert not kwargs

    def _new_node(self, node_name, **kwargs):
        if self.ns_uri is None:
            return etree.Element(node_name, **kwargs)
        else:
            return etree.Element("{" + self.ns_uri + "}" + node_name,
                                 nsmap={self.ns_prefix: self.ns_uri},
                                 **kwargs)

    def _text_node(self, node_name, value, **kwargs):
        child = self._new_node(node_name, **kwargs)
        if value is not None:
            child.text = str(value)
        return child

    def format_dom(self):
        return self._new_node(self.root_name)

    def parse_str(self, xmlstr):
        try:
            self.parse_dom(etree.fromstring(xmlstr))
        except etree.Error:
            LOG.debug("Failed to parse the libvirt XML: %s", xmlstr)
            raise

    def parse_dom(self, xmldoc):
        if self.root_name != xmldoc.tag:
            msg = (_("Root element name should be '%(name)s' not '%(tag)s'") %
                   {'name': self.root_name, 'tag': xmldoc.tag})
            raise exception.InvalidInput(msg)

    def to_xml(self, pretty_print=True):
        root = self.format_dom()
        xml_str = etree.tostring(root, encoding='unicode',
                                 pretty_print=pretty_print)
        return xml_str

    @classmethod
    def parse_on_off_str(self, value: str | None) -> bool:
        if value is not None and value not in ('on', 'off'):
            msg = _(
                "Element should contain either 'on' or 'off'; "
                "found: '%(value)s'"
            )
            raise exception.InvalidInput(msg % {'value': value})

        return value == 'on'

    @classmethod
    def get_yes_no_str(self, value: bool) -> str:
        return 'yes' if value else 'no'

    @classmethod
    def get_on_off_str(self, value: bool) -> str:
        return 'on' if value else 'off'

    def __repr__(self):
        return self.to_xml(pretty_print=False)


class LibvirtConfigCaps(LibvirtConfigObject):

    def __init__(self, **kwargs):
        super(LibvirtConfigCaps, self).__init__(root_name="capabilities",
                                                **kwargs)
        self.host = None
        self.guests = []

    def parse_dom(self, xmldoc):
        super(LibvirtConfigCaps, self).parse_dom(xmldoc)

        for c in xmldoc:
            if c.tag == "host":
                host = LibvirtConfigCapsHost()
                host.parse_dom(c)
                self.host = host
            elif c.tag == "guest":
                guest = LibvirtConfigCapsGuest()
                guest.parse_dom(c)
                self.guests.append(guest)

    def format_dom(self):
        caps = super(LibvirtConfigCaps, self).format_dom()

        if self.host:
            caps.append(self.host.format_dom())
        for g in self.guests:
            caps.append(g.format_dom())

        return caps


class LibvirtConfigDomainCaps(LibvirtConfigObject):

    def __init__(self, **kwargs):
        super(LibvirtConfigDomainCaps, self).__init__(
            root_name="domainCapabilities", **kwargs)
        self._features = None
        self._machine = None
        self._alias = None
        self._devices = None
        self._os = None

    def parse_dom(self, xmldoc):
        super(LibvirtConfigDomainCaps, self).parse_dom(xmldoc)

        for c in xmldoc:
            if c.tag == "features":
                features = LibvirtConfigDomainCapsFeatures()
                features.parse_dom(c)
                self._features = features
            elif c.tag == "machine":
                self._machine = c.text
            elif c.tag == "devices":
                devices = LibvirtConfigDomainCapsDevices()
                devices.parse_dom(c)
                self._devices = devices
            elif c.tag == "os":
                os = LibvirtConfigDomainCapsOS()
                os.parse_dom(c)
                self._os = os

    @property
    def features(self):
        if self._features is None:
            return []
        return self._features.features

    @property
    def machine_type(self):
        if self._machine is None:
            return ""
        return self._machine

    @property
    def machine_type_alias(self):
        if self._alias is None:
            return self._machine
        return self._alias

    @machine_type_alias.setter
    def machine_type_alias(self, alias):
        self._alias = alias

    @property
    def devices(self):
        if self._devices is None:
            return []
        return self._devices

    @property
    def os(self):
        return self._os


class LibvirtConfigDomainCapsVideoModels(LibvirtConfigObject):

    def __init__(self, **kwargs):
        super().__init__(root_name='video', **kwargs)
        self.supported = False
        self.models = set()

    def parse_dom(self, xmldoc):
        super().parse_dom(xmldoc)

        if xmldoc.get('supported') == 'yes':
            self.supported = True
        self.models = {str(node) for node in
                       xmldoc.xpath("//enum[@name='modelType']/value/text()")}


class LibvirtConfigDomainCapsDiskBuses(LibvirtConfigObject):

    def __init__(self, **kwargs):
        super().__init__(root_name='disk', **kwargs)
        self.supported = False
        self.buses = set()

    def parse_dom(self, xmldoc):
        super(LibvirtConfigDomainCapsDiskBuses, self).parse_dom(xmldoc)

        if xmldoc.get('supported') == 'yes':
            self.supported = True
        self.buses = {str(node) for node in
                      xmldoc.xpath("//enum[@name='bus']/value/text()")}


class LibvirtConfigDomainCapsTpm(LibvirtConfigObject):

    def __init__(self, **kwargs):
        super().__init__(root_name='tpm', **kwargs)
        self.supported = False
        self.models = []
        self.backend_models = []
        # TODO(tkajinam): Change default to [] once libvirt >= 8.6.0 is
        #                 required
        self.backend_versions = None

    def parse_dom(self, xmldoc):
        super(LibvirtConfigDomainCapsTpm, self).parse_dom(xmldoc)

        if xmldoc.get('supported'):
            self.supported = (xmldoc.get('supported') == 'yes')
        for c in xmldoc:
            if c.tag == 'enum':
                if c.get('name') == 'model':
                    for c2 in c:
                        if c2.tag == 'value':
                            self.models.append(c2.text)
                if c.get('name') == 'backendModel':
                    for c2 in c:
                        if c2.tag == 'value':
                            self.backend_models.append(c2.text)
                if c.get('name') == 'backendVersion':
                    for c2 in c:
                        if c2.tag == 'value':
                            if self.backend_versions is None:
                                self.backend_versions = []
                            self.backend_versions.append(c2.text)


class LibvirtConfigDomainCapsDevices(LibvirtConfigObject):
    DEVICE_PARSERS = {
        'video': LibvirtConfigDomainCapsVideoModels,
        'disk': LibvirtConfigDomainCapsDiskBuses,
        'tpm': LibvirtConfigDomainCapsTpm,
    }

    def __init__(self, **kwargs):
        super().__init__(root_name='devices', **kwargs)
        self.devices = set()

    def parse_dom(self, xmldoc):
        super().parse_dom(xmldoc)

        for c in list(xmldoc):
            device = self.DEVICE_PARSERS.get(c.tag)
            if device:
                device = device()
                device.parse_dom(c)
                self.devices.add(device)

    def _get_device(self, device_type):
        for device in self.devices:
            if type(device) is self.DEVICE_PARSERS.get(device_type):
                return device
        return None

    @property
    def disk(self):
        return self._get_device('disk')

    @property
    def video(self):
        return self._get_device('video')

    @property
    def tpm(self):
        return self._get_device('tpm')


